namespace NotificationsApp.Services;

public record Notification(int Id, string Message, DateTime Timestamp);

public class NotificationService
{
    private readonly List<Notification> _notifications = new();
    private int _nextId = 1;
    private readonly Lock _lock = new();

    public NotificationService()
    {
        // Seed with initial fake data.
        _notifications.Add(new(NextId(), "Welcome to the app!", DateTime.UtcNow.AddMinutes(-10)));
        _notifications.Add(new(NextId(), "Your profile was updated.", DateTime.UtcNow.AddMinutes(-5)));
        _notifications.Add(new(NextId(), "New feature: dark mode is available.", DateTime.UtcNow.AddMinutes(-2)));
    }

    /// <summary>Returns all notifications ordered newest-first.</summary>
    public List<Notification> GetAll()
    {
        lock (_lock)
        {
            return _notifications.OrderByDescending(n => n.Timestamp).ToList();
        }
    }

    /// <summary>Returns only notifications with Id greater than <paramref name="sinceId"/>.</summary>
    public List<Notification> GetSince(int sinceId)
    {
        lock (_lock)
        {
            return _notifications
                .Where(n => n.Id > sinceId)
                .OrderByDescending(n => n.Timestamp)
                .ToList();
        }
    }

    /// <summary>Simulates an external system pushing a new notification.</summary>
    public void AddRandom()
    {
        string[] templates =
        [
            "Server health check passed.",
            "A new user signed up.",
            "Deployment #{{id}} completed.",
            "Disk usage alert on node-3.",
            "Backup finished successfully.",
            "CI pipeline succeeded for main.",
        ];

        var msg = templates[Random.Shared.Next(templates.Length)]
            .Replace("{{id}}", Random.Shared.Next(100, 999).ToString());

        lock (_lock)
        {
            _notifications.Add(new(NextId(), msg, DateTime.UtcNow));
        }
    }

    private int NextId() => _nextId++;
}

